import {test,expect,type Page,type TestInfo} from '@playwright/test';
import {randomUUID} from 'node:crypto';
import {writeFile} from 'node:fs/promises';
import {seed as seedCorrection,produce,seedBatch} from './corrections-ui';
import {seeded,chooseOne,actualSubmission,cmd,login,ctx,json,mutation} from './campaigns-ui';
import type {CompletionWorkspace} from '@/server/completion/service';
export {login,ctx,json,mutation,produce};
export const workspace=(page:Page,id:string)=>json<CompletionWorkspace>(page.request,`/api/completion?taskId=${id}`);
export const button=(page:Page,name:string)=>page.getByRole('button',{name,exact:true});
export const field=(page:Page,name:string)=>page.getByRole('textbox',{name,exact:true});
export async function open(page:Page,id:string){await page.goto(`/tasks/${id}/completion?context=${ctx}`);await expect(button(page,'현재 저장본 다시 확인')).toBeVisible();await expect(page.getByText('현재 권한과 저장본을 확인하는 중입니다.',{exact:true})).toHaveCount(0);}
export async function tab(page:Page,name:string){await page.getByRole('navigation',{name:'완료·외부 진행 화면',exact:true}).getByRole('button',{name,exact:true}).click();}
export async function saved(page:Page,complete=false){await expect(page.getByRole('status').filter({hasText:complete?'업무 완료 기록을 저장했습니다.':'기록을 저장했습니다.'})).toBeVisible();await expect(page.getByRole('heading',{name:'저장은 완료됐습니다',exact:true})).toHaveCount(0);}
export async function seed(page:Page){const x=await seedCorrection(page);await seedBatch(page,x.v1,1);return x;}
export async function inquiry(page:Page,taskId:string){await login(page,'luna@example.test');const r=await mutation(page.request,'/api/inquiries',{contextId:ctx,taskId,idempotencyKey:randomUUID()});expect(r.status(),await r.text()).toBe(201);const d=await r.json();let response=await mutation(page.request,`/api/inquiries/${d.conversationId}`,{command:'publish_first',expectedRevision:d.revision,title:'외부 확인 문의',content:{clientMessageId:randomUUID(),body:'PUBLIC_G11_QUESTION',fileVersionIds:[]},idempotencyKey:randomUUID()});expect(response.status(),await response.text()).toBe(200);await login(page);const detail=await json<{questions:{id:string;revision:number}[]}>(page.request,`/api/inquiries/${d.conversationId}`),q=detail.questions[0];response=await mutation(page.request,`/api/inquiries/${d.conversationId}`,{command:'state',questionId:q.id,expectedQuestionRevision:q.revision,state:'external_waiting',reason:'외부 회신 대기',externalWait:{counterparty:'합성 기관',sentAt:'2026-09-22T09:00:00+09:00',responsibleUserId:'user-gsg',nextCheckDate:'2026-10-01',timezone:'Asia/Seoul',latestResult:'회신 대기'},idempotencyKey:randomUUID()});expect(response.status(),await response.text()).toBe(200);return d.conversationId as string;}
export async function campaignSeed(page:Page){const x=await seeded(page);await chooseOne(page,x.taskId,x.id);const actual=await actualSubmission(page,x.taskId);await login(page);await seedBatch(page,actual.w.latest!,1);await cmd(page,x.id,'external',{campaignVersionId:x.versionId,menu:x.draft.menus[0].identity,fact:{axis:'application',value:'applied',requester:{kind:'user',userId:'user-luna'},performedBy:{kind:'user',userId:'user-gsg'},occurredAt:null,source:{source:'합성 기록',sourceVersion:'v1',locator:'p1',language:'ko',originalText:'신청 사실',translatedText:'',fileVersionIds:[]},note:''}});await login(page,'luna@example.test');await cmd(page,x.id,'participate',{campaignVersionId:x.versionId,response:'decline',selectedMenus:[],providedBy:{kind:'user',userId:'user-luna'},note:''});await inquiry(page,x.taskId);return {...x,actual};}
export async function complete(page:Page){await button(page,'현재 기준으로 업무 완료').click();await saved(page,true);}
export function journeys(){test.beforeEach(async({page})=>{await page.context().tracing.start({screenshots:true,snapshots:true,sources:true});});test.afterEach(async({page},info)=>{await writeFile(info.outputPath('final-private.html'),await page.content());await page.screenshot({path:info.outputPath('final-private.png'),fullPage:true});await page.context().tracing.stop({path:info.outputPath('journey-private.zip')});});}
export async function record(info:TestInfo,name:string,data:unknown){await writeFile(info.outputPath(name+'.json'),JSON.stringify(data,null,2));}
